import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"API 参考","description":"两份未过滤平面契约：openapi.client.json（客户端与商店）与 openapi.admin.json（管理后台与 CI）。下载或在新窗口打开 Scalar。","frontmatter":{"title":"API 参考","description":"两份未过滤平面契约：openapi.client.json（客户端与商店）与 openapi.admin.json（管理后台与 CI）。下载或在新窗口打开 Scalar。"},"headers":[],"relativePath":"api/reference/index.md","filePath":"api/reference/index.md","lastUpdated":1790057721000}`),a={name:`api/reference/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h1><p>KiriVers 有两个 HTTP 平面。文档站构建时把运行中进程使用的同一份契约文件原样复制到本站，<strong>不</strong>再按路径切成四份。</p><table tabindex="0"><thead><tr><th>平面</th><th>契约文件</th><th>覆盖</th></tr></thead><tbody><tr><td>客户端</td><td><code>openapi.client.json</code></td><td>原生 JSON（check、下载、差量、公告等）<strong>和</strong>商店 <code>/store/</code> feed</td></tr><tr><td>管理后台</td><td><code>openapi.admin.json</code></td><td>控制台自动化 <strong>和</strong> CI Token / <code>ci/releases</code></td></tr></tbody></table><p>对照：</p><ul><li><strong>客户端 / 商店</strong>：<code>openapi.client.json</code></li><li><strong>管理后台 / CI</strong>：<code>openapi.admin.json</code></li></ul><p>运行中各平面 <code>GET /api/v1/openapi.json</code> 与下表下载文件来自同一源。字段表以契约为准，教程页不手抄 schema。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h2><ul><li><a href="/openapi/openapi.client.json" download="openapi.client.json"><code>openapi.client.json</code></a></li><li><a href="/openapi/openapi.admin.json" download="openapi.admin.json"><code>openapi.admin.json</code></a></li></ul><h2 id="在新窗口浏览-scalar" tabindex="-1">在新窗口浏览 Scalar <a class="header-anchor" href="#在新窗口浏览-scalar" aria-label="Permalink to “在新窗口浏览 Scalar”">​</a></h2><p>Scalar 是全屏契约浏览器，<strong>不</strong>嵌在带侧栏的文档页里。请用新窗口打开：</p><ul><li><a href="/api/scalar/client" target="_blank" rel="noopener">客户端 / 商店 Scalar</a></li><li><a href="/api/scalar/admin" target="_blank" rel="noopener">管理后台 / CI Scalar</a></li></ul><p>相关教程：<a href="/api/client/">客户端调用</a>、<a href="/api/admin/">管理后台自动化</a>、<a href="/api/ci">自动发版</a>、<a href="/api/conventions">调用约定</a>。失败码见 <a href="/faq/errors">FAQ · 失败代码对照</a>。</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};